//! Minimal re-implementation of the `tsl::hopscotch_map` interface used by
//! the test program, backed by `std::collections::HashMap`.
//!
//! Only the operations exercised by the test are provided:
//! `insert` and `equal_range`.

use std::collections::HashMap;
use std::hash::Hash;

/// A hash map with unique keys, mirroring the semantics of
/// `tsl::hopscotch_map` for the subset of the API used here.
pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    /// Creates an empty map.
    pub fn new() -> Self {
        HopscotchMap {
            inner: HashMap::new(),
        }
    }

    /// Inserts a key-value pair. If the key already exists, the old value
    /// is kept (matching `std::map`-style `insert` semantics) and `false`
    /// is returned as the second tuple element.
    pub fn insert(&mut self, key: K, value: V) -> bool {
        if self.inner.contains_key(&key) {
            false
        } else {
            self.inner.insert(key, value);
            true
        }
    }

    /// Returns an iterator over the range of elements matching `key`.
    /// Since keys are unique, the range contains at most one element.
    pub fn equal_range(&self, key: &K) -> EqualRange<'_, K, V> {
        EqualRange {
            item: self.inner.get_key_value(key),
        }
    }
}

/// Iterator over the result of `equal_range`: yields zero or one item.
pub struct EqualRange<'a, K, V> {
    item: Option<(&'a K, &'a V)>,
}

impl<'a, K, V> Iterator for EqualRange<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        self.item.take()
    }
}

