//! Rust port of `tests/test15.cpp`.
//!
//! Inserts `count` entries into a hopscotch map, then counts how many
//! elements fall in `equal_range(count / 2)` (0 or 1 for a unique-key map).

mod hopscotch_map;

use hopscotch_map::HopscotchMap;

/// Parses an integer the way `std::stoi` does: optional leading
/// whitespace, optional sign, then digits. Panics on invalid input.
fn stoi(s: &str) -> i32 {
    let trimmed = s.trim_start();
    let (sign, digits) = match trimmed.strip_prefix('-') {
        Some(rest) => (-1i64, rest),
        None => match trimmed.strip_prefix('+') {
            Some(rest) => (1i64, rest),
            None => (1i64, trimmed),
        },
    };
    let digit_len = digits
        .bytes()
        .take_while(|b| b.is_ascii_digit())
        .count();
    if digit_len == 0 {
        panic!("stoi: no conversion could be performed");
    }
    let value: i64 = digits[..digit_len]
        .parse()
        .expect("stoi: no conversion could be performed");
    let value = sign * value;
    if value < i32::MIN as i64 || value > i32::MAX as i64 {
        panic!("stoi: out of range");
    }
    value as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut count: i32 = 15;
    if args.len() > 1 && args[1] == "--a" {
        count = stoi(&args[2]);
    }

    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    let mut i: i32 = 0;
    while i < count {
        map.insert(i, i.wrapping_mul(12));
        i += 1;
    }

    let num_in_range = map.equal_range(&(count / 2)).count();

    println!("{}", num_in_range);
}

